style.css:
@-moz-document domain("lichess.org") {
.piece {
    background-image: none !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
  }

  /* White pieces */
  .piece[data-piece="wK"] {
    background-image: url("https://upload.wikimedia.org/wikipedia/commons/4/42/Chess_klt60.png");
  }
  .piece[data-piece="wQ"] {
    background-image: url("https://upload.wikimedia.org/wikipedia/commons/1/15/Chess_qlt60.png");
  }
  .piece[data-piece="wR"] {
    background-image: url("https://upload.wikimedia.org/wikipedia/commons/7/72/Chess_rlt60.png");
  }
  .piece[data-piece="wB"] {
    background-image: url("https://upload.wikimedia.org/wikipedia/commons/b/b1/Chess_blt60.png");
  }
  .piece[data-piece="wN"] {
    background-image: url("https://upload.wikimedia.org/wikipedia/commons/7/70/Chess_nlt60.png");
  }
  .piece[data-piece="wP"] {
    background-image: url("https://upload.wikimedia.org/wikipedia/commons/4/45/Chess_plt60.png");
  }

  /* Black pieces */
  .piece[data-piece="bK"] {
    background-image: url("https://upload.wikimedia.org/wikipedia/commons/f/f0/Chess_kdt60.png");
  }
  .piece[data-piece="bQ"] {
    background-image: url("https://upload.wikimedia.org/wikipedia/commons/4/47/Chess_qdt60.png");
  }
  .piece[data-piece="bR"] {
    background-image: url("https://upload.wikimedia.org/wikipedia/commons/f/ff/Chess_rdt60.png");
  }
  .piece[data-piece="bB"] {
    background-image: url("https://upload.wikimedia.org/wikipedia/commons/9/98/Chess_bdt60.png");
  }
  .piece[data-piece="bN"] {
    background-image: url("https://upload.wikimedia.org/wikipedia/commons/e/ef/Chess_ndt60.png");
  }
  .piece[data-piece="bP"] {
    background-image: url("https://upload.wikimedia.org/wikipedia/commons/c/c7/Chess_pdt60.png");
  }

  /* Optional: make sure pieces look sharp */
  .piece {
    image-rendering: auto !important;
  }
}
